class Solution:
    def maxDistinctPathSum(self, root):
        NEG = float('-inf')
        ans = NEG
        def dfs(node):
            nonlocal ans
            if not node:
                return {}
            L, R = dfs(node.left), dfs(node.right)
            v = node.val
            cur = {frozenset([v]): v}
            for src in (L, R):
                for s, val in src.items():
                    if v in s:
                        continue
                    ns = s | {v}
                    nv = val + v
                    if cur.get(ns, NEG) < nv:
                        cur[ns] = nv
            for sl, vl in L.items():
                if v in sl:
                    continue
                for sr, vr in R.items():
                    if v in sr or (sl & sr):
                        continue
                    ans = max(ans, vl + v + vr)
            for val in cur.values():
                ans = max(ans, val)
            return cur
        dfs(root)
        return ans

