class Solution {
    long long ans = LLONG_MIN;
    map<set<int>, long long> dfs(TreeNode* node) {
        if (!node) return {};
        auto L = dfs(node->left), R = dfs(node->right);
        int v = node->val;
        map<set<int>, long long> cur;
        cur[{v}] = v;
        for (auto* src : {&L, &R})
            for (auto& [s, val] : *src) {
                if (s.count(v)) continue;
                set<int> ns = s; ns.insert(v);
                long long nv = val + v;
                if (cur[ns] < nv) cur[ns] = nv;
            }
        for (auto& [sl, vl] : L) {
            if (sl.count(v)) continue;
            for (auto& [sr, vr] : R) {
                if (sr.count(v)) continue;
                bool disjoint = true;
                for (int x : sl) if (sr.count(x)) { disjoint = false; break; }
                if (disjoint) ans = max(ans, vl + v + vr);
            }
        }
        for (auto& [s, val] : cur) ans = max(ans, val);
        return cur;
    }
public:
    int maxDistinctPathSum(TreeNode* root) {
        dfs(root);
        return (int) ans;
    }
};

