class Solution {
    private long ans = Long.MIN_VALUE;
    private Map<Set<Integer>, Long> dfs(TreeNode node) {
        if (node == null) return new HashMap<>();
        Map<Set<Integer>, Long> L = dfs(node.left), R = dfs(node.right);
        int v = node.val;
        Map<Set<Integer>, Long> cur = new HashMap<>();
        cur.put(new HashSet<>(List.of(v)), (long) v);
        for (Map<Set<Integer>, Long> src : List.of(L, R))
            for (var e : src.entrySet()) {
                if (e.getKey().contains(v)) continue;
                Set<Integer> ns = new HashSet<>(e.getKey()); ns.add(v);
                long nv = e.getValue() + v;
                cur.merge(ns, nv, Math::max);
            }
        for (var el : L.entrySet()) {
            if (el.getKey().contains(v)) continue;
            for (var er : R.entrySet()) {
                if (er.getKey().contains(v)) continue;
                boolean disjoint = Collections.disjoint(el.getKey(), er.getKey());
                if (disjoint) ans = Math.max(ans, el.getValue() + v + er.getValue());
            }
        }
        for (long x : cur.values()) ans = Math.max(ans, x);
        return cur;
    }
    public int maxDistinctPathSum(TreeNode root) {
        dfs(root);
        return (int) ans;
    }
}

