var maxDistinctPathSum = function(root) {
    let ans = -Infinity;
    const dfs = node => {
        if (!node) return new Map();
        const L = dfs(node.left), R = dfs(node.right);
        const v = node.val;
        const cur = new Map();
        cur.set(JSON.stringify([v]), v);
        for (const src of [L, R])
            for (const [key, val] of src) {
                const s = JSON.parse(key);
                if (s.includes(v)) continue;
                s.push(v); s.sort((a, b) => a - b);
                const nk = JSON.stringify(s), nv = val + v;
                if (!cur.has(nk) || cur.get(nk) < nv) cur.set(nk, nv);
            }
        for (const [lk, lv] of L) {
            const ls = JSON.parse(lk);
            if (ls.includes(v)) continue;
            for (const [rk, rv] of R) {
                const rs = JSON.parse(rk);
                if (rs.includes(v) || ls.some(x => rs.includes(x))) continue;
                ans = Math.max(ans, lv + v + rv);
            }
        }
        for (const val of cur.values()) ans = Math.max(ans, val);
        return cur;
    };
    dfs(root);
    return ans;
};
